<script setup lang="ts">
import { t, formatDate } from '../i18n'
import {computed,onUnmounted,ref,watch} from 'vue'
import {api} from '../api/client'
import {readPreference,updatePreference} from '../api/preferences'
import {manageFolder} from '../api/reading'
import type {Account} from '../api/accounts'
import {generateSieve,newSieveRule,simulateSieve,type SieveRule} from '../api/sieveRules'
import {useSessionStore} from '../stores/session'
import {useSieveSeed} from '../stores/sieveSeed'
const props=defineProps<{accounts:Account[]}>()
type Connection={host:string;port:number;security:'tls'|'starttls';username:string;password:string}
type Backup={name:string;script:string;savedAt:number}
type Saved={id:string;connection:Connection;rules:SieveRule[];liked:string[];disliked:string[];screen:string;accountID:string;backups:Backup[]}
type Result={scripts:{name:string;active:boolean}[];extensions:string[];script?:string;hash?:string}
const empty=():Saved=>({id:'sieve-settings',connection:{host:'',port:4190,security:'starttls',username:'',password:''},rules:[],liked:[],disliked:[],screen:'Screen Emails',accountID:'',backups:[]})
const session=useSessionStore(),seed=useSieveSeed(),enabled=ref(false),data=ref<Saved>(empty()),remote=ref<Result>({scripts:[],extensions:[]}),name=ref(''),script=ref(''),loadedName=ref(''),hash=ref(''),busy=ref(false),error=ref(''),notice=ref(''),confirm=ref(''),sender=ref(''),simulation=ref('')
const activeName=computed(()=>remote.value.scripts.find(s=>s.active)?.name||'')
let generation=0,controller=new globalThis.AbortController()
function clear(){generation++;controller.abort();controller=new globalThis.AbortController();data.value=empty();remote.value={scripts:[],extensions:[]};name.value='';script.value='';loadedName.value='';hash.value='';error.value='';notice.value='';confirm.value='';sender.value='';simulation.value='';busy.value=false}
const current=(g:number)=>g===generation&&session.unlocked
watch(()=>[session.unlocked,session.vaultEpoch,session.userID],async()=>{clear();if(!session.unlocked)return;const g=generation
 try{const available=await api<{sieve:boolean}>('/connectors/options');if(!current(g))return;enabled.value=available.sieve;if(!available.sieve)return
 const saved=await readPreference<Saved>('sieve-settings',empty);if(current(g)){data.value={...empty(),...saved};if(seed.seed)data.value.accountID=seed.seed.accountID}}
 catch(value){if(current(g))error.value=value instanceof Error?value.message:'Could not load filtering settings.'}
},{immediate:true})
onUnmounted(clear)
async function run(action:()=>Promise<void>){if(busy.value||!session.unlocked)return;const g=generation;busy.value=true;error.value='';notice.value=''
 try{await action()}catch(value){if(current(g))error.value=value instanceof Error?value.message:'Sieve request failed. Check the remote result before retrying a change.'}finally{if(current(g))busy.value=false}}
async function request(action:string,extra:Record<string,string>={}){return api<Result>('/sieve',{method:'POST',signal:controller.signal,body:JSON.stringify({...data.value.connection,action,lock_revision:session.serverLockRevision,...extra})})}
function snapshot(){return JSON.parse(JSON.stringify(data.value)) as Saved}
async function persist(){const saved=snapshot();await updatePreference<Saved>('sieve-settings',empty,r=>Object.assign(r,saved))}
function save(){const g=generation;void run(async()=>{await persist();if(current(g))notice.value='Connection, rule drafts and backups saved encrypted. No server script was changed.'})}
function list(){const g=generation;void run(async()=>{const result=await request('list');if(current(g))remote.value=result})}
function load(){const g=generation,chosen=name.value;void run(async()=>{const result=await request('get',{name:chosen});if(current(g)){remote.value=result;loadedName.value=chosen;script.value=result.script||'';hash.value=result.hash||'';confirm.value=''}})}
function check(){const g=generation;void run(async()=>{await request('check',{script:script.value});if(current(g))notice.value='Server syntax check passed. This does not simulate delivery.'})}
function fresh(){name.value=`emailer-${Date.now()}`;loadedName.value='';hash.value='';confirm.value=''}
function generate(){error.value='';try{const generated=generateSieve(data.value.rules,remote.value.extensions);fresh();script.value=generated;notice.value='Generated into a new draft. Validate and save, then activate explicitly.'}catch(value){error.value=value instanceof Error?value.message:'Invalid rules.'}}
function put(){const g=generation,chosen=name.value,body=script.value,previous=hash.value,active=activeName.value
 void run(async()=>{
  if(!chosen.trim()||chosen.length>128||new globalThis.TextEncoder().encode(body).length>65536)throw new Error('Enter a script name and keep content under 64 KiB.')
  if(previous&&chosen!==loadedName.value)throw new Error('Choose New script before changing the loaded name.')
  if(chosen===active&&confirm.value!==chosen)throw new Error('Type the active script name to confirm replacing live rules.')
  if(previous){const before=await request('get',{name:chosen});if(before.hash!==previous)throw new Error('The remote script changed. Reload it before saving.');if(!current(g))return
   data.value.backups=[{name:chosen,script:before.script||'',savedAt:Date.now()},...data.value.backups].slice(0,5);await persist();if(!current(g))return}
  const result=await request('put',{name:chosen,script:body,expected_hash:previous,expected_active:active});if(!current(g))return
  loadedName.value=chosen;hash.value=result.hash||'';confirm.value='';const next=await request('list');if(current(g)){remote.value=next;notice.value=chosen===active?'Active script updated.':'Script saved inactive. Activate it explicitly to change delivery rules.'}
 })}
function mutate(action:'activate'|'delete'|'deactivate'){const g=generation,chosen=name.value,active=activeName.value;void run(async()=>{
 const target=action==='deactivate'?active:chosen;if(!target||confirm.value!==target)throw new Error('Type the script name to confirm this remote change.')
 if(action!=='deactivate'&&(!hash.value||loadedName.value!==chosen))throw new Error('Load the remote script before changing it.')
 await request(action,{name:chosen,expected_hash:hash.value,expected_active:active});if(!current(g))return
 const next=await request('list');if(current(g)){remote.value=next;confirm.value='';notice.value='Remote change confirmed.';if(action==='delete'){loadedName.value='';hash.value=''}}
 })}
function move(index:number,delta:number){const target=index+delta;if(target<0||target>=data.value.rules.length)return;const [rule]=data.value.rules.splice(index,1);data.value.rules.splice(target,0,rule!)}
function fromMessage(field:'from'|'subject'='from'){if(!seed.seed)return;const rule=newSieveRule();rule.name=field==='from'?'From selected sender':'Selected subject';rule.conditions[0]!.field=field;rule.conditions[0]!.value=field==='from'?seed.seed.from[0]||'':seed.seed.subject;data.value.rules.push(rule);notice.value='Sender condition copied. Choose an action before generating a script.'}
function classify(liked:boolean){const email=sender.value.trim().toLowerCase();if(!/^[^\s<>@]+@[^\s<>@]+$/.test(email)||email.length>254){error.value='Enter a valid sender address.';return}
 const list=liked?data.value.liked:data.value.disliked;if(list.length>=100){error.value='Keep each sender list under 100 entries.';return}
 if(!list.includes(email))list.push(email);data.value.liked=data.value.liked.filter(x=>liked||x!==email);data.value.disliked=data.value.disliked.filter(x=>!liked||x!==email)}
function buildLists(){if(!data.value.screen){error.value='Choose a Screen folder.';return}const rules:SieveRule[]=[]
 for(const [senders,liked] of [[data.value.liked,true],[data.value.disliked,false]] as const)for(const email of senders){const rule=newSieveRule();rule.id=`sender-list:${liked?'like':'screen'}:${email}`;rule.name=`${liked?'Like':'Screen'} ${email}`;rule.conditions[0]!.value=email;rule.action=liked?'keep':'fileinto';rule.destination=liked?'':data.value.screen;rules.push(rule)}
 const manual=data.value.rules.filter(r=>!r.id.startsWith('sender-list:'));if(rules.length+manual.length>50){error.value='The graphical editor supports at most 50 rules. Narrow the sender lists.';return};data.value.rules=[...manual,...rules];notice.value='Sender rule drafts refreshed. Review order, generate, validate, save and activate explicitly.'}
function createScreen(){const g=generation;void run(async()=>{if(!data.value.accountID||!data.value.screen.trim())throw new Error('Choose the corresponding mailbox and destination folder.');await manageFolder(data.value.accountID,'create',data.value.screen,'','',controller.signal);if(current(g))notice.value='Folder creation confirmed. Existing names or quota errors do not rename or replace folders.'})}
function simulate(){if(!seed.seed){simulation.value='Open a message and choose Create server rule to supply headers.';return}try{generateSieve(data.value.rules,remote.value.extensions);const matches=simulateSieve(data.value.rules,seed.seed);simulation.value=matches.length?matches.map(r=>`${r.name}: ${r.action}${r.destination?' '+r.destination:''}${r.stop?' (stop)':''}`).join('; '):'No generated rule matches these headers.'}catch(value){simulation.value=value instanceof Error?value.message:'Invalid rules.'}}
</script>
<template><section id="sieve"><h2>{{ t("Server mail rules") }}</h2><p v-if="!enabled">{{ t("ManageSieve is disabled by the administrator. Existing mail remains available.") }}</p>
<details v-else :open="!!seed.seed"><summary>{{ t("ManageSieve connection and scripts") }}</summary><p>{{ t("Rules run on the mail provider. Saving a local draft does not activate it. Remote changes are checked immediately before writing; ManageSieve has no atomic compare-and-swap. Avoid editing the same script from two clients.") }}</p>
<fieldset :disabled="busy"><label>{{ t("Host") }}<input v-model="data.connection.host" maxlength="253" /></label><label>{{ t("Port") }}<input v-model.number="data.connection.port" type="number" min="1" max="65535" /></label><label>{{ t("Security") }}<select v-model="data.connection.security"><option value="starttls">{{ t("Required STARTTLS") }}</option><option value="tls">{{ t("Verified implicit TLS") }}</option></select></label><label>{{ t("Username") }}<input v-model="data.connection.username" autocomplete="off" /></label><label>{{ t("Password") }}<input v-model="data.connection.password" type="password" autocomplete="new-password" /></label>
<button type="button" class="secondary" @click="save">{{ t("Save encrypted settings and drafts") }}</button><button type="button" class="secondary" @click="list">{{ t("Connect / reload script list") }}</button><p>{{ t("Extensions:") }} {{remote.extensions.join(', ')||t('Connect to detect capabilities')}}</p>
<label>{{ t("Remote scripts") }}<select v-model="name"><option value="">{{ t("Select script") }}</option><option v-for="item in remote.scripts" :key="item.name" :value="item.name">{{item.name}}{{item.active?t(" (active)"):''}}</option></select></label><button type="button" class="secondary" @click="load">{{ t("Load selected script") }}</button><button type="button" class="secondary" @click="fresh">{{ t("New script") }}</button>
<label>{{ t("Script name") }}<input v-model="name" maxlength="128" /></label><label>{{ t("Custom Sieve script") }}<textarea v-model="script" maxlength="65536" rows="12" spellcheck="false" /></label><p>{{ t("Custom scripts are never parsed or overwritten by the graphical editor. Generation creates a new draft.") }}</p>
<button type="button" class="secondary" @click="check">{{ t("Check syntax on server") }}</button><button type="button" class="secondary" @click="put">{{ t("Validate and save remote script") }}</button>
<label>{{ t("Type the script name to confirm activation, deletion or replacement of live rules") }}<input v-model="confirm" autocomplete="off" /></label><button type="button" @click="mutate('activate')">{{ t("Activate loaded script") }}</button><button type="button" class="secondary" @click="mutate('deactivate')">{{ t("Deactivate") }} {{activeName||t('active script')}}</button><button type="button" class="secondary" @click="mutate('delete')">{{ t("Delete inactive script") }}</button>
<details><summary>{{ t("Previous encrypted versions (last five)") }}</summary><button v-for="(backup,i) in data.backups" :key="i" type="button" class="secondary" @click="fresh();script=backup.script">{{ t("Restore") }} {{backup.name}} — {{formatDate(backup.savedAt)}} {{ t("into a new draft") }}</button></details>
<details><summary>{{ t("Graphical rule drafts") }}</summary><p>{{ t("Rules run in this order. Discard deletes matching incoming mail; redirect sends it to the chosen address. Review before activation.") }}</p><button v-if="seed.seed" type="button" class="secondary" @click="fromMessage()">{{ t("Add sender condition from selected message") }}</button><button v-if="seed.seed?.subject" type="button" class="secondary" @click="fromMessage('subject')">{{ t("Add subject condition from selected message") }}</button><button type="button" class="secondary" :disabled="data.rules.length>=50" @click="data.rules.push(newSieveRule())">{{ t("Add rule") }}</button>
<div v-for="(rule,index) in data.rules" :key="rule.id" class="rule"><label><input v-model="rule.enabled" type="checkbox" />{{ t("Enabled") }}</label><label>{{ t("Name") }}<input v-model="rule.name" maxlength="128" /></label><label>{{ t("Match") }}<select v-model="rule.mode"><option value="all">{{ t("ALL conditions") }}</option><option value="any">{{ t("ANY condition") }}</option></select></label>
<div v-for="(condition,i) in rule.conditions" :key="i"><label>{{ t("Header") }}<select v-model="condition.field"><option value="from">{{ t("From address") }}</option><option value="to">{{ t("To address") }}</option><option value="subject">{{ t("Subject") }}</option></select></label><label>{{ t("Comparison") }}<select v-model="condition.match"><option value="is">{{ t("is") }}</option><option value="contains">{{ t("contains") }}</option></select></label><label>{{ t("Value") }}<input v-model="condition.value" maxlength="1024" /></label><button type="button" class="text-button" :disabled="rule.conditions.length<2" @click="rule.conditions.splice(i,1)">{{ t("Remove condition") }}</button></div>
<button type="button" class="secondary" :disabled="rule.conditions.length>=10" @click="rule.conditions.push({field:'subject',match:'contains',value:''})">{{ t("Add condition") }}</button><label>{{ t("Action") }}<select v-model="rule.action"><option value="keep">{{ t("Keep") }}</option><option value="fileinto" :disabled="!remote.extensions.includes('fileinto')">{{ t("Move to folder") }}</option><option value="redirect">{{ t("Redirect") }}</option><option value="discard">{{ t("Discard (destructive)") }}</option><option value="flag" :disabled="!remote.extensions.includes('imap4flags')">{{ t("Set flag and keep") }}</option></select></label>
<label v-if="rule.action==='fileinto'||rule.action==='redirect'">{{ t("Destination") }}<input v-model="rule.destination" maxlength="1024" /></label><label v-if="rule.action==='flag'">{{ t("Flag") }}<select v-model="rule.destination"><option value="\Seen">{{ t("Seen") }}</option><option value="\Flagged">{{ t("Starred") }}</option><option value="\Answered">{{ t("Answered") }}</option></select></label><label><input v-model="rule.stop" type="checkbox" />{{ t("Stop after this rule") }}</label><button type="button" class="secondary" :disabled="index===0" @click="move(index,-1)">{{ t("Move up") }}</button><button type="button" class="secondary" :disabled="index===data.rules.length-1" @click="move(index,1)">{{ t("Move down") }}</button><button type="button" class="text-button" @click="data.rules.splice(index,1)">{{ t("Remove rule") }}</button></div>
<button type="button" class="secondary" @click="generate">{{ t("Generate into new script draft") }}</button><button type="button" class="secondary" @click="simulate">{{ t("Simulate generated rules on selected headers") }}</button><p v-if="simulation" role="status">{{t(simulation)}}</p><p>{{ t("Simulation covers these From/To/Subject conditions only. It does not execute custom scripts, check folder existence or reproduce all provider behavior.") }}</p></details>
<details><summary>{{ t("Like / screen sender lists") }}</summary><label>{{ t("Sender address") }}<input v-model="sender" type="email" /></label><button type="button" class="secondary" @click="classify(true)">{{ t("Like (keep)") }}</button><button type="button" class="secondary" @click="classify(false)">{{ t("Screen (move)") }}</button><ul><li v-for="email in data.liked" :key="'like'+email">{{ t("Like") }} {{email}} <button type="button" class="text-button" @click="data.liked=data.liked.filter(x=>x!==email)">{{ t("Undo") }}</button></li><li v-for="email in data.disliked" :key="'screen'+email">{{ t("Screen") }} {{email}} <button type="button" class="text-button" @click="data.disliked=data.disliked.filter(x=>x!==email)">{{ t("Undo") }}</button></li></ul>
<label>{{ t("Corresponding IMAP mailbox") }}<select v-model="data.accountID"><option value="">{{ t("Choose mailbox") }}</option><option v-for="account in props.accounts" :key="account.id" :value="account.id">{{account.name}}</option></select></label><label>{{ t("Screen folder") }}<input v-model="data.screen" maxlength="1024" /></label><button type="button" class="secondary" @click="createScreen">{{ t("Create Screen folder explicitly") }}</button><button type="button" class="secondary" @click="buildLists">{{ t("Refresh sender rule drafts from lists") }}</button><p>{{ t("Removing a list entry changes the local draft. Regenerate and activate a reviewed script to update live filtering.") }}</p></details>
</fieldset></details><p v-if="error" class="error" role="alert">{{t(error)}}</p><p v-if="notice" role="status">{{t(notice)}}</p></section></template>
<style scoped>fieldset{display:grid;gap:.65rem}.rule{border:1px solid var(--line);padding:1rem;margin-block:.8rem}textarea{font-family:monospace;min-width:0;width:100%}details{margin-block:.8rem}label{display:grid;gap:.25rem}</style>
